#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    int row = strtol(argv[1], NULL, 10);
    if (row < 0) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (row == 0) {
        printf("1\n");
        return 0;
    }
    long long *triangle = (long long *)calloc(row + 1, sizeof(long long));
    triangle[0] = 1;
    for (int i = 1; i <= row; i++) {
        triangle[i] = 1;
        for (int j = 1; j < i; j++) {
            triangle[j] = triangle[j] + triangle[j - 1];
        }
        for (int j = 0; j <= i; j++) {
            printf("%lld ", triangle[j]);
        }
        printf("\n");
    }
    free(triangle);
    return 0;
}
